import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTORS = {"lowvol": 0.50, "clv": 0.18, "peer": 0.13, "momentum": 0.10, "volume_rev": 0.05, "total_rev": 0.04}
REBALANCE_EVERY = 10
MIN_WEIGHT, MAX_WEIGHT = 0.02, 0.14
_calls = 0


def rank_cross(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    result = {s: 0.5 for s in UNIVERSE}
    if len(valid) == 1:
        result[valid[0][0]] = 0.5
    elif valid:
        for i, (s, _) in enumerate(valid):
            result[s] = (i + 1.0) / len(valid)
    return result


def bounded_weights(raw):
    # Iterative water filling keeps all 15 assets invested and within bounds.
    active = set(UNIVERSE)
    out = {}
    for _ in range(30):
        remaining = 1.0 - sum(out.values())
        denom = sum(max(raw[s], 1e-9) for s in active)
        trial = {s: remaining * max(raw[s], 1e-9) / denom for s in active}
        clipped = False
        for s, w in list(trial.items()):
            if w < MIN_WEIGHT:
                out[s] = MIN_WEIGHT; active.remove(s); clipped = True
            elif w > MAX_WEIGHT:
                out[s] = MAX_WEIGHT; active.remove(s); clipped = True
        if not clipped:
            out.update(trial)
            break
    if active:
        out.update({s: (1.0 - sum(out.values())) / len(active) for s in active})
    total = sum(out.values())
    return {s: out.get(s, MIN_WEIGHT) / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _calls
    _calls += 1
    if _calls != 1 and (_calls - 1) % REBALANCE_EVERY != 0:
        return

    raw_factors = {k: {} for k in FACTORS}
    vol, momentum = {}, {}
    five_day = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=90)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        o = np.asarray(df["open"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        l = np.asarray(df["low"], dtype=float)
        if np.any(~np.isfinite(c[-30:])) or np.any(c[-30:] <= 0):
            continue
        ret = c[1:] / c[:-1] - 1.0
        sigma = max(float(np.std(ret[-20:])), 0.008)
        vol[symbol] = sigma
        one_day = ret[-1]
        raw_factors["lowvol"][symbol] = -one_day / sigma
        raw_factors["momentum"][symbol] = (c[-1] / c[-21] - 1.0) / (sigma + 0.01)
        momentum[symbol] = raw_factors["momentum"][symbol]
        span = h[-1] - l[-1]
        raw_factors["clv"][symbol] = (c[-1] - l[-1]) / span if np.isfinite(span) and span > 0 else 0.5
        overnight = o[-1] / c[-2] - 1.0
        intraday = c[-1] / o[-1] - 1.0 if o[-1] > 0 else 0.0
        total_rev = -(overnight + intraday) / sigma
        raw_factors["total_rev"][symbol] = total_rev
        # Missing/zero volume is neutral, per screener guidance.
        if "volume" in df.columns:
            vv = np.asarray(df["volume"], dtype=float)
            if len(vv) >= 21 and np.isfinite(vv[-1]) and vv[-1] > 0 and np.nanmedian(vv[-21:]) > 0:
                confirmation = min(max(vv[-1] / np.nanmedian(vv[-21:]), 0.25), 2.0)
                raw_factors["volume_rev"][symbol] = (-one_day / sigma) * (0.75 + 0.25 * confirmation)
            else:
                raw_factors["volume_rev"][symbol] = 0.0
        else:
            raw_factors["volume_rev"][symbol] = 0.0
        if len(c) >= 6:
            five_day[symbol] = c[-1] / c[-6] - 1.0

    if len(vol) < 8:
        return
    for symbol in vol:
        peers = [five_day[s] for s in vol if s != symbol and s in five_day]
        raw_factors["peer"][symbol] = five_day.get(symbol, 0.0) - (float(np.median(peers)) if peers else 0.0)

    ranks = {k: rank_cross(v) for k, v in raw_factors.items()}
    score = {s: sum(FACTORS[k] * ranks[k][s] for k in FACTORS) for s in UNIVERSE}
    breadth = np.mean([momentum[s] > 0 for s in momentum]) if momentum else 0.5
    avg_inv_vol = np.mean([1.0 / v for v in vol.values()])
    defensive = {"XAU", "US10Y", "CN10Y"}
    raw = {}
    for s in UNIVERSE:
        inv = min((1.0 / vol[s]) / avg_inv_vol, 1.8) if s in vol else 1.0
        risk_tilt = 1.16 if breadth < 0.50 and s in defensive else (0.94 if breadth < 0.50 else 1.0)
        raw[s] = max(score[s], 0.05) * (0.94 + 0.06 * inv) * risk_tilt
    rebalance_to_weights(bounded_weights(raw))

