# Current Screener ensemble; all directions are positive as supplied.
FACTORS = {"peer5": .20, "mom20": .16, "clv": .15, "lowvol1": .14,
           "stress": .09, "beta5": .09, "rev3": .07, "lagmix": .05, "beta2": .05}
MIN_W, MAX_W, CADENCE = .02, .14, 10
_day = 0

def rank(x):
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.) / len(good)
    return out

def bounded(raw):
    # Iterative water filling enforces a complete, finite, long-only vector.
    w = {s: max(float(raw.get(s, 0)), 1e-8) for s in UNIVERSE}
    fixed, active = {}, set(UNIVERSE)
    for _ in range(30):
        left = 1 - sum(fixed.values()); den = sum(w[s] for s in active)
        trial = {s: left*w[s]/den for s in active}
        clipped = False
        for s, q in list(trial.items()):
            if q < MIN_W: fixed[s] = MIN_W; active.remove(s); clipped = True
            elif q > MAX_W: fixed[s] = MAX_W; active.remove(s); clipped = True
        if not clipped:
            fixed.update(trial); break
    z = sum(fixed.values())
    return {s: fixed.get(s, 0.)/z for s in UNIVERSE}

