import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble (directions are positive: higher score is preferred).
FACTORS = {"clv": .296, "peer5": .227, "volume1": .214, "mom20": .173, "rev3": .090}
MIN_W, MAX_W, CADENCE = .02, .14, 10
_day = 0

def cross_rank(values):
    valid = [(s, v) for s, v in values.items() if np.isfinite(v)]
    valid.sort(key=lambda x: x[1])
    out = {s: .5 for s in UNIVERSE}
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.) / n
    return out

def bound_weights(raw):
    # Water-filling projection onto the complete long-only bounded simplex.
    fixed, active = {}, set(UNIVERSE)
    base = {s: max(float(raw.get(s, 0.1)), 1e-8) for s in UNIVERSE}
    for _ in range(40):
        left = 1.0 - sum(fixed.values())
        denom = sum(base[s] for s in active)
        trial = {s: left * base[s] / denom for s in active}
        clipped = False
        for s, w in list(trial.items()):
            if w < MIN_W:
                fixed[s] = MIN_W; active.remove(s); clipped = True
            elif w > MAX_W:
                fixed[s] = MAX_W; active.remove(s); clipped = True
        if not clipped:
            fixed.update(trial); break
    total = sum(fixed.values())
    return {s: fixed.get(s, 0.0) / total for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE != 0:
        return

    ret, vol, raw = {}, {}, {k: {} for k in FACTORS}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=140)
        if df is None or len(df) < 35:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        try:
            c = np.asarray(df["close"], float); o = np.asarray(df["open"], float)
            h = np.asarray(df["high"], float); l = np.asarray(df["low"], float)
            v = np.asarray(df["volume"], float)
        except Exception:
            continue
        if np.any(~np.isfinite(c[-35:])) or np.any(c[-35:] <= 0):
            continue
        r = c[1:] / c[:-1] - 1
        if len(r) < 30: continue
        sigma = max(float(np.nanstd(r[-20:])), .008)
        ret[symbol], vol[symbol] = r, sigma
        span = h[-1] - l[-1]
        # Conventional CLV reversal: buy assets closing near the bottom of range.
        raw["clv"][symbol] = -(2*c[-1] - h[-1] - l[-1]) / span if span > 0 else 0.
        raw["mom20"][symbol] = (c[-1]/c[-21]-1) / (sigma*np.sqrt(20)+.01)
        vol_med = np.nanmedian(v[-21:-1])
