    base = {s: max(float(raw.get(s, 0.1)), 1e-12) for s in UNIVERSE}
    active, fixed = set(UNIVERSE), {}
    for _ in range(40):
        left = 1.0 - sum(fixed.values())
        denom = sum(base[s] for s in active)
        if denom <= 0:
            break
        trial = {s: left * base[s] / denom for s in active}
        changed = False
        for s, w in list(trial.items()):
            if w < MIN_W:
                fixed[s] = MIN_W; active.remove(s); changed = True
            elif w > MAX_W:
                fixed[s] = MAX_W; active.remove(s); changed = True
        if not changed:
            fixed.update(trial)
            break
    # Numerical normalization preserves non-negative full investment.
    ans = {s: fixed.get(s, 0.0) for s in UNIVERSE}
    total = sum(ans.values())
    return {s: ans[s] / total for s in UNIVERSE} if total > 0 else {s: 1.0 / len(UNIVERSE) for s in UNIVERSE}


