import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
# Current screener ensemble: nine active factors, all directions positive as specified.
FACTORS = {
    "volume": .16, "stress": .15, "dispersion": .15, "rev3": .12,
    "range": .12, "rev10": .10, "rev15": .08, "residual": .07,
    "intraday": .05,
}
CADENCE = 10
MIN_W, MAX_W = .035, .16
_day = 0
_previous = None


def pct_rank(values):
    out = {s: .5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def bounded_weights(raw):
    # Iterative water-filling keeps all 15 assets invested and within sensible bounds.
    w = {s: max(float(raw.get(s, 1.0)), 1e-10) for s in UNIVERSE}
    fixed = set()
    for _ in range(30):
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        base = sum(w[s] for s in free)
        if base <= 0 or not free:
            break
        for s in free:
            w[s] = rem * w[s] / base
        newly = {s for s in free if w[s] < MIN_W or w[s] > MAX_W}
        if not newly:
            break
        for s in newly:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        fixed |= newly
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _day, _previous
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE != 0:
        return

    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=270)
        if df is None or len(df) < 160:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], float)
        o = np.asarray(df["open"], float)
        if np.any(~np.isfinite(c)) or np.any(c <= 0):
            continue
        r = c[1:] / c[:-1] - 1.0
        vol = max(float(np.std(r[-30:])), .006)
        down = max(float(np.std(np.minimum(r[-40:], 0))), .004)
        volume = np.asarray(df["volume"], float) if "volume" in df else np.ones(len(c))
        volume[~np.isfinite(volume)] = 0
        data[s] = {
            "r": r, "vol": vol, "down": down,
            "h3": float(np.prod(1+r[-3:])-1), "h5": float(np.prod(1+r[-5:])-1),
            "h10": float(np.prod(1+r[-10:])-1), "h15": float(np.prod(1+r[-15:])-1),
            "h20": float(np.prod(1+r[-20:])-1), "h120": float(np.prod(1+r[-120:])-1),
            "intraday": float(np.nanmean((c[-5:] - o[-5:]) / np.maximum(o[-5:], 1e-12))),
            "vr": float(np.mean(volume[-5:]) / max(np.mean(volume[-20:]), 1e-9)),
            "range": float(np.nanmean((np.asarray(df["high"])[-5:] - np.asarray(df["low"])[-5:]) / c[-5:])),
        }
    if len(data) < 10:
        return

    syms = list(data)
    med = {n: np.median([data[s][n] for s in syms]) for n in ("h3", "h5", "h10", "h15", "h20")}
    f = {k: {} for k in FACTORS}
    for s in syms:
        d = data[s]
        f["volume"][s] = (med["h5"]-d["h5"])/(d["vol"]*np.sqrt(5)+.01) * (.75+.25*np.clip(d["vr"], .5, 1.5))
        f["stress"][s] = (med["h20"]-d["h20"])/(d["down"]*np.sqrt(20)+.02)
        f["dispersion"][s] = (med["h20"]-d["h20"])/(d["vol"]*np.sqrt(20)+.015)
        f["rev3"][s] = (med["h3"]-d["h3"])/(d["vol"]*np.sqrt(3)+.008)
        f["range"][s] = (med["h5"]-d["h5"])/(d["range"]+.01)
        f["rev10"][s] = (med["h10"]-d["h10"])/(d["vol"]*np.sqrt(10)+.01)
        f["rev15"][s] = (med["h15"]-d["h15"])/(d["vol"]*np.sqrt(15)+.012)
        f["residual"][s] = .7*f["stress"][s] + .3*f["dispersion"][s]
        f["intraday"][s] = -d["intraday"]/(d["vol"]+.01)
    ranks = {k: pct_rank(v) for k, v in f.items()}
    score = {s: sum(FACTORS[k]*ranks[k].get(s, .5) for k in FACTORS) for s in UNIVERSE}
    if _previous is not None:
        score = {s: .35*score[s] + .65*_previous.get(s, .5) for s in UNIVERSE}
    _previous = score.copy()

    breadth = np.mean([data[s]["h120"] > 0 for s in syms])
    median_vol = np.median([data[s]["vol"] for s in syms])
    high_risk = median_vol > .018 or breadth < .50
    inv_mean = np.mean([1.0/data[s]["vol"] for s in syms])
    raw = {}
    for s in UNIVERSE:
        d = data.get(s, {"vol": .02, "h120": 0.0})
        inv = (1.0/d["vol"]) / max(inv_mean, 1e-9)
        raw[s] = max(score[s], .10) * (.88 + .12*min(inv, 1.25))
        if high_risk and s in DEFENSIVE:
            raw[s] *= 3.0
        if high_risk and d["h120"] < -.10:
            raw[s] *= .60
    target = bounded_weights(raw)
    if abs(sum(target.values())-1.0) < 1e-8 and all(np.isfinite(x) and x >= 0 for x in target.values()):
        rebalance_to_weights(target)

import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
# Screener's current ten-factor ensemble; directions are positive reversal ranks.
FACTORS = {"disp": .15, "vix": .13, "volshock": .12, "ranges": .10,
           "volconfirm": .10, "rev10": .10, "shock3": .06,
           "intraday": .08, "rev15": .08, "smooth5": .08}
CADENCE = 10
MIN_W, MAX_W = .035, .16
_day = 0
_previous = None


def rank(x):
    out = {s: .5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.) / n
    return out


def bounded(raw):
    # Water filling enforces a complete, long-only, full-investment vector.
    w = {s: max(float(raw.get(s, 1.)), 1e-12) for s in UNIVERSE}
    fixed = set()
    for _ in range(40):
        free = [s for s in UNIVERSE if s not in fixed]
        if not free:
            break
        rem = 1. - sum(w[s] for s in fixed)
        z = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / z
        hit = {s for s in free if w[s] < MIN_W or w[s] > MAX_W}
        if not hit:
            break
        for s in hit:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        fixed |= hit
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _day, _previous
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE != 0:
        return
    d = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=270)
        if df is None or len(df) < 160:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], float)
        o = np.asarray(df["open"], float)
        hi = np.asarray(df["high"], float)
        lo = np.asarray(df["low"], float)
        if np.any(~np.isfinite(c)) or np.any(c <= 0):
            continue
        r = c[1:] / c[:-1] - 1.
        vol5 = max(float(np.std(r[-5:])), .006)
        vol20 = max(float(np.std(r[-20:])), .006)
        vol60 = max(float(np.std(r[-60:])), .006)
        v = np.asarray(df["volume"], float) if "volume" in df else np.ones(len(c))
        v = np.nan_to_num(v, nan=0.)
        d[s] = dict(h3=np.prod(1+r[-3:])-1, h5=np.prod(1+r[-5:])-1,
                    h10=np.prod(1+r[-10:])-1, h15=np.prod(1+r[-15:])-1,
                    h20=np.prod(1+r[-20:])-1, h120=np.prod(1+r[-120:])-1,
                    vol5=vol5, vol20=vol20, vol60=vol60,
                    vr5=np.mean(v[-5:]) / max(np.mean(v[-20:]), 1e-9),
                    intraday=np.nanmean((c[-5:]-o[-5:]) / np.maximum(o[-5:], 1e-12)),
                    ranges=np.nanmean((hi[-5:]-lo[-5:]) / c[-5:]))
    if len(d) < 10:
        return
    syms = list(d)
    med = {k: np.median([d[s][k] for s in syms]) for k in ("h3","h5","h10","h15","h20")}
    f = {k: {} for k in FACTORS}
    for s in syms:
        x = d[s]
